 let defaults=SqliteDatabaseLimits::default();let text=plan["text"].as_str().unwrap();assert_eq!(text.len(),plan["textBytes"].as_u64().unwrap()as usize);
 for(index,sample)in plan["cases"].as_array().unwrap().iter().enumerate(){
  let source=semantic_role_source(index,text);let bytes=sample["semanticBytes"].as_u64().unwrap()as usize;
  let database=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();
  let file=export_sqlite_database(&database,defaults,&mut |_|true).unwrap();
  let script=r###"import Ajv from "ajv/dist/2020";import{Database}from "bun:sqlite";const plan=JSON.parse(process.argv[1]),schema=JSON.parse(process.argv[2]),sample=JSON.parse(process.argv[3]);const validate=new Ajv({strict:true}).compile(schema);if(!validate(plan)||validate({...plan,unknown:true}))throw Error("closed complete semantic corpus");if(Buffer.byteLength(plan.text,"utf8")!==plan.textBytes)throw Error("independent UTF8 extent");const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const quote=v=>'"'+v.replaceAll('"','""')+'"';try{if(db.query("PRAGMA integrity_check").get().integrity_check!=="ok"||db.query("PRAGMA foreign_key_check").all().length)throw Error("independent physical integrity");let rows=0,bytes=0;for(const[table,count]of Object.entries(plan.tableRows)){const fields=db.query("PRAGMA table_info("+quote(table)+")").all().map(v=>v.name);const cells=fields.map(v=>{const f=quote(v);return "CASE typeof("+f+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+f+" AS BLOB)) WHEN 'blob' THEN length("+f+") ELSE 0 END";}).join("+");const actual=db.query("SELECT COUNT(*) AS rows,COALESCE(SUM("+cells+"),0) AS bytes FROM "+quote(table)).get();if(actual.rows!==count)throw Error("authored row extent "+table);rows+=actual.rows;bytes+=actual.bytes;}if(rows!==plan.rows||bytes!==sample.semanticBytes)throw Error("independent complete cell extent "+JSON.stringify({rows,bytes}));}finally{db.close();}"###;
  let mut child=Command::new("bun").args(["-e",script]).arg(plan.to_string()).arg(schema.to_string()).arg(sample.to_string()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
  child.stdin.take().unwrap().write_all(&file).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}: {}",sample["id"],String::from_utf8_lossy(&result.stderr));
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
   let input=payload(&source,encoding);
   let retained=SpaceSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();assert_eq!(retained,source);retained.retire_sqlite_snapshot();
   let short=SqliteDatabaseLimits{max_columns_per_table:8-1,..defaults};
   assert!(SpaceSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err(),"{} borrowed complete native columns must refuse before typed materialization",sample["id"]);
   for maximum in[bytes-1,bytes]{
    let limits=SqliteDatabaseLimits{max_value_bytes:maximum,..defaults};
    let output=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));
    assert_eq!(output.is_ok(),maximum==bytes,"{} complete typed semantic output cells",sample["id"]);
    let preflight=source.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));
    assert_eq!(preflight.is_ok(),maximum==bytes,"{} complete borrowed semantic preflight cells",sample["id"]);
   }
  }
  source.retire_sqlite_snapshot();
 }
}

